import { buildTransformMetrics, longestSharedWordRun } from "./metrics";
import { extractInvariantValues, restoreProtectedText, tokenOccurrenceCount } from "./protect";
import type { PreparedText, ProtectedSpan, TransformMode, TransformValidation } from "./types";

const LENGTH_BOUNDS: Record<TransformMode, [number, number]> = {
  parity: [0.90, 1.10],
  natural: [0.75, 1.25],
  clarity: [0.7, 1.3],
  concise: [0.45, 1.02],
  formal: [0.75, 1.3],
};

function arraysEqual(a: string[], b: string[]) {
  return a.length === b.length && a.every((value, index) => value === b[index]);
}

function withoutProtectedTokens(text: string, spans: ProtectedSpan[]) {
  let result = text;
  for (const span of spans) result = result.split(span.token).join(" ");
  return result;
}

export function validateTransformedDraft(prepared: PreparedText, protectedDraft: string, mode: TransformMode): TransformValidation {
  const errors: string[] = [];
  const warnings: string[] = [];
  let protectedPreserved = 0;
  let numericDateEntityPreserved = 0;
  let quoteReferencePreserved = 0;
  const numericDateEntityExpected = prepared.spans.filter(span => span.kind === "number" || span.kind === "date" || span.kind === "entity").length;
  const quoteReferenceExpected = prepared.spans.filter(span => span.kind === "quote" || span.kind === "citation").length;

  for (const span of prepared.spans) {
    const count = tokenOccurrenceCount(protectedDraft, span.token);
    if (count === 1) {
      protectedPreserved += 1;
      if (span.kind === "number" || span.kind === "date" || span.kind === "entity") numericDateEntityPreserved += 1;
      if (span.kind === "quote" || span.kind === "citation") quoteReferencePreserved += 1;
    } else errors.push(`${span.kind} placeholder ${span.token} occurred ${count} times; expected exactly once.`);
  }

  const restoredText = errors.length ? null : restoreProtectedText(protectedDraft.trim(), prepared.spans);
  const outputForMetrics = restoredText ?? protectedDraft;
  const metrics = buildTransformMetrics(prepared.original, outputForMetrics, prepared.spans.length, protectedPreserved);
  const unprotectedRun = longestSharedWordRun(withoutProtectedTokens(prepared.protectedText, prepared.spans), withoutProtectedTokens(protectedDraft, prepared.spans));
  metrics.unprotectedLongestSharedWordRun = unprotectedRun;

  if (restoredText) {
    const sourceInvariants = extractInvariantValues(prepared.original);
    const outputInvariants = extractInvariantValues(restoredText);
    if (!arraysEqual(sourceInvariants, outputInvariants)) errors.push("A protected factual invariant was added, removed, or changed.");
  }

  const [minimum, maximum] = LENGTH_BOUNDS[mode];
  if (metrics.lengthRatio < minimum || metrics.lengthRatio > maximum) errors.push(`Length ratio ${metrics.lengthRatio.toFixed(2)} is outside the ${minimum.toFixed(2)}–${maximum.toFixed(2)} range for ${mode} mode.`);
  if (mode === "parity" && unprotectedRun > 3) errors.push(`Parity mode retained ${unprotectedRun} consecutive unprotected source words; maximum allowed is 3.`);

  if (restoredText?.trim() === prepared.original.trim()) warnings.push("The output is effectively unchanged from the source.");
  if (mode !== "parity" && unprotectedRun > 30) warnings.push("A long unprotected source phrase remains unchanged; review whether the edit was meaningful enough for your purpose.");

  return {
    ok: errors.length === 0,
    errors,
    warnings,
    restoredText,
    metrics,
    checks: {
      protectedSpansPreserved: protectedPreserved === prepared.spans.length,
      numericDateEntityExpected,
      numericDateEntityPreserved,
      quoteReferenceExpected,
      quoteReferencePreserved,
    },
  };
}

const $ = (id) => document.getElementById(id);
const fields = ["apiKey", "apiBase", "mode", "intensity", "purpose"];

async function activeTab() {
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  return tab;
}

function setStatus(message, error = false) {
  $("status").textContent = message;
  $("status").className = error ? "status error" : "status";
}

async function loadSettings() {
  const saved = await chrome.storage.local.get(fields);
  $("apiKey").value = saved.apiKey || "";
  $("apiBase").value = saved.apiBase || "https://provenance-cleaner.vercel.app";
  $("mode").value = saved.mode || "parity";
  $("intensity").value = saved.intensity || "balanced";
  $("purpose").value = saved.purpose || "general";
}

async function saveSettings() {
  const payload = Object.fromEntries(fields.map((id) => [id, $(id).value.trim()]));
  await chrome.storage.local.set(payload);
  setStatus("Settings saved. Content is not stored.");
}

async function sendToPage(message) {
  const tab = await activeTab();
  if (!tab?.id) throw new Error("No active tab.");
  return chrome.tabs.sendMessage(tab.id, message);
}

async function rewriteSelection() {
  setStatus("Reading selected text…");
  const selected = await sendToPage({ type: "selection" });
  if (!selected?.ok || !selected.text) throw new Error(selected?.reason || "Select text first.");
  if (selected.text.trim().length < 20) throw new Error("Select at least 20 characters.");

  const apiKey = $("apiKey").value.trim();
  if (!apiKey) throw new Error("Add a developer API key first.");
  const base = $("apiBase").value.trim().replace(/\/$/u, "");
  const body = {
    operationId: crypto.randomUUID(),
    text: selected.text,
    mode: $("mode").value,
    intensity: $("intensity").value,
    purpose: $("purpose").value,
  };

  setStatus("Running protected rewrite…");
  const response = await fetch(`${base}/api/v1/transform`, {
    method: "POST",
    headers: { "content-type": "application/json", authorization: `Bearer ${apiKey}` },
    body: JSON.stringify(body),
  });
  const payload = await response.json();
  if (!response.ok) throw new Error(payload?.error?.message || payload?.error || "Rewrite failed.");

  $("output").value = payload.text;
  $("outputBox").hidden = false;
  if (selected.editable) {
    const replaced = await sendToPage({ type: "replace", text: payload.text });
    if (!replaced?.ok) throw new Error(replaced?.reason || "Result was generated but could not be placed in the page.");
    setStatus(`Validated and replaced in page · ${payload.purpose}/${payload.intensity}. Undo is available.`);
  } else {
    setStatus("Validated result is ready. The original selection is read-only, so copy the result instead.");
  }
}

$("rewrite").addEventListener("click", () => rewriteSelection().catch((error) => setStatus(error.message, true)));
$("undo").addEventListener("click", () => sendToPage({ type: "undo" }).then((result) => {
  if (!result?.ok) throw new Error(result?.reason || "Could not undo.");
  setStatus("Last in-page rewrite undone.");
}).catch((error) => setStatus(error.message, true)));
$("save").addEventListener("click", () => saveSettings().catch((error) => setStatus(error.message, true)));
$("copy").addEventListener("click", () => navigator.clipboard.writeText($("output").value).then(() => setStatus("Result copied.")).catch(() => setStatus("Could not copy result.", true)));
void loadSettings();

